-- Cover education foreign keys in the leading-column order used by PostgreSQL FK checks.
create index if not exists education_departments_campus_fk_idx on public.education_departments(campus_id,organization_id) where campus_id is not null;
create index if not exists education_departments_hod_fk_idx on public.education_departments(hod_member_id,organization_id) where hod_member_id is not null;
create index if not exists education_programs_department_fk_idx on public.education_programs(department_id,organization_id) where department_id is not null;
create index if not exists education_batches_program_fk_idx on public.education_batches(program_id,organization_id);
create index if not exists education_batches_academic_year_fk_idx on public.education_batches(academic_year_id,organization_id);
create index if not exists education_students_campus_fk_idx on public.education_students(campus_id,organization_id) where campus_id is not null;
create index if not exists education_students_department_fk_idx on public.education_students(department_id,organization_id) where department_id is not null;
create index if not exists education_students_batch_fk_idx on public.education_students(batch_id,organization_id) where batch_id is not null;
create index if not exists education_students_user_fk_idx on public.education_students(user_id) where user_id is not null;
create index if not exists education_faculty_campus_fk_idx on public.education_faculty(campus_id,organization_id) where campus_id is not null;
create index if not exists education_faculty_department_fk_idx on public.education_faculty(department_id,organization_id) where department_id is not null;
create index if not exists education_faculty_member_fk_idx on public.education_faculty(member_id,organization_id) where member_id is not null;
create index if not exists education_subjects_program_fk_idx on public.education_subjects(program_id,organization_id);
create index if not exists education_subjects_department_fk_idx on public.education_subjects(department_id,organization_id) where department_id is not null;
create index if not exists education_enrollments_student_fk_idx on public.education_enrollments(student_id,organization_id);
create index if not exists education_enrollments_batch_fk_idx on public.education_enrollments(batch_id,organization_id);
create index if not exists education_enrollments_year_fk_idx on public.education_enrollments(academic_year_id,organization_id);
create index if not exists education_timetable_batch_fk_idx on public.education_timetable_entries(batch_id,organization_id);
create index if not exists education_timetable_subject_fk_idx on public.education_timetable_entries(subject_id,organization_id);
create index if not exists education_timetable_faculty_fk_idx on public.education_timetable_entries(faculty_id,organization_id);
create index if not exists education_attendance_sessions_batch_fk_idx on public.education_attendance_sessions(batch_id,organization_id);
create index if not exists education_attendance_sessions_subject_fk_idx on public.education_attendance_sessions(subject_id,organization_id);
create index if not exists education_attendance_sessions_faculty_fk_idx on public.education_attendance_sessions(faculty_id,organization_id);
create index if not exists education_attendance_records_session_fk_idx on public.education_attendance_records(session_id,organization_id);
create index if not exists education_attendance_records_student_fk_idx on public.education_attendance_records(student_id,organization_id);
create index if not exists education_attendance_records_marked_by_fk_idx on public.education_attendance_records(marked_by) where marked_by is not null;
